# std pkg
import asyncio
import json
import logging
import os.path

# nodom
import nd_consts
import nd_utils
import nd_web

# 3rd pty
import tornado

# slimgui for the convenience of autogenerated table/window flag enums only
# we don't invoke any imgui behaviour here on the server side
# https://nurpax.github.io/slimgui/#enum-reference
from slimgui.imgui import InputTextFlags, WindowFlags
from tornado.options import define, options, parse_command_line

NDAPP = "qed_server"

logr = nd_utils.init_logging(NDAPP, console=True)

QED_LAYOUT = [
    dict(
        rname="Home",
        cspec=dict(
            title="Query Editor",
            title_font="Arial",
        ),
        children=[
            dict(rname="PushFont", cspec=dict(font="CourierNew")),
            dict(
                rname="Combo",
                cspec=dict(
                    cname="queries",
                    cindex="selected_query",
                    label="Query",
                ),
            ),
            dict(rname="InputTextArea", cspec=dict(
                cname="queries selected_query []",
                buffer_size=64)),
            dict(rname="Separator", cspec=dict()),
            dict(rname="PopFont"),
            dict(rname="PushFont", cspec=dict(font="Arial", font_size=8)),
            dict(
                rname="Footer",
                cspec=dict(
                    db=True,
                    fps=True,
                    demo=True,
                    font_scale=True,
                    style=True,
                ),
            ),
            dict(rname="Spacing", cspec=dict()),
            dict(rname="DebugFooter",cspec=dict()),
            dict(rname="PopFont"),
        ],
    ),
    dict(
        widget_id="qed_modal",
        rname="LoadingModal",
        cspec=dict(
            title="QED modal...",
            title_font="Arial",
            body_font="CourierNew",
            cname="loading_message",
            spinner_radius=20,
            spinner_thickness=4,
        ),
    ),
]

SCAN_SQL = "BEGIN; DROP TABLE IF EXISTS depth; CREATE TABLE depth as select * from read_parquet(%s); COMMIT;"
QUERY_SQL = "select * from depth where LastTradeSize!=0 and AskQty5!=0 and BidQty5!=0 order by SeqNo;"
SUMMARY_SQL = "summarize select * from depth;"


QED_DATA = dict(
    queries=[
        SCAN_SQL,
        QUERY_SQL,
        SUMMARY_SQL
    ],
    selected_query=0,
    loading_message=["Loading queries..."],
)


class QueryEditService(nd_utils.Service):
    def on_client_data_change(self, uuid, client_change):
        logr.info(f"on_client_data_change:client:{uuid}, change:{client_change}")
        return []


# breadboard looks out for service at the module level
service = QueryEditService(NDAPP, QED_LAYOUT, QED_DATA)

# default to 8890 for http. Override to 443 for https
define("port", default=8890, help="run on the given port", type=int)


async def http_main():
    app = nd_web.NDApp(service)
    app.listen(options.port)
    logr.info(f"{NDAPP} port:{options.port}")
    await asyncio.Event().wait()


async def https_main():
    cert_path = os.path.normpath(os.path.join(nd_consts.ND_ROOT_DIR, "cfg"))
    app = nd_web.NDApp(service)
    https_server = tornado.httpserver.HTTPServer(
        app,
        ssl_options={
            "certfile": os.path.join(cert_path, "ssl_cert.pem"),
            "keyfile": os.path.join(cert_path, "ssl_key.pem"),
        },
    )
    https_server.listen(options.port)
    logr.info(f"{NDAPP} port:{options.port} cert_path:{cert_path}")
    await asyncio.Event().wait()


if __name__ == "__main__":
    parse_command_line()
    if options.port == 443:
        asyncio.run(https_main())
    else:
        asyncio.run(http_main())
